```// K6 built in modules
import { check, sleep, fail } from "k6";

// K6 testing options
export let options = {
    stages: [
        { duration: "5s", target: 5 },
        { duration: "30s" },
        { duration: "5s", target: 0 }
    ]
};

export default function() {
    sleep(0.1);

    var date = new Date();
    
    check(date, {
        "milliseconds < 500": (r) => r.getMilliseconds() < 500
    }) || fail("milliseconds >= 500");
};
```
